package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;

/**
 * Normalizes the owner's telephone on create into E.164 form, mutating the validated request in
 * place so later steps store and return the E.164 value. Spaces, dashes and brackets are stripped.
 * A leading '+' and its country code are kept as given; otherwise country code '+61' is assumed and
 * a single leading '0' is dropped from the national digits (so {@code 0412 345 678} becomes
 * {@code +61412345678}). The result must carry 8 to 15 digits after the '+'; anything that cannot
 * form valid E.164 is rejected 400 via {@link InvalidTelephoneException}.
 */
public class NormalizeOwnerTelephone {

    public void service(@Val OwnerFieldsDto request) throws InvalidTelephoneException {
        request.setTelephone(toE164(request.getTelephone()));
    }

    /**
     * The single source of truth for what "same telephone" means: converts a raw telephone into its
     * E.164 form. Spaces, dashes and brackets are removed; a leading '+' and country code are kept,
     * otherwise '+61' is assumed and a single leading '0' is dropped from the national digits. The
     * digits after the '+' must number 8 to 15, and no other characters may remain. Shared with
     * {@link CheckOwnerTelephoneUnique} so the request side and stored owners are normalized
     * identically.
     *
     * @throws InvalidTelephoneException if the value cannot form valid E.164.
     */
    static String toE164(String telephone) throws InvalidTelephoneException {
        if (telephone == null) {
            throw invalid();
        }
        String cleaned = telephone.replaceAll("[\\s\\-()]", "");
        String digits;
        if (cleaned.startsWith("+")) {
            digits = cleaned.substring(1);
        }
        else {
            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
            digits = "61" + national;
        }
        if (!digits.matches("\\d{8,15}")) {
            throw invalid();
        }
        return "+" + digits;
    }

    private static InvalidTelephoneException invalid() {
        return new InvalidTelephoneException(
                "Telephone must form a valid E.164 number with 8 to 15 digits after the '+'");
    }
}
===== CheckOwnerHouseholdUnique =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateHouseholdException;

/**
 * Rejects creating an owner who shares a household with an existing owner: same lastName
 * AND same address, each compared case-insensitively with collapsed whitespace. A
 * collision is rejected 409 via {@link DuplicateHouseholdException}, unless the request
 * opts in with {@code sharesHousehold=true}, in which case the check is bypassed.
 */
public class CheckOwnerHouseholdUnique {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateHouseholdException {
        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
            return;
        }
        for (Owner existing : ownerRepository.findAll()) {
            if (sameHousehold(request.getLastName(), request.getAddress(),
                    existing.getLastName(), existing.getAddress())) {
                throw new DuplicateHouseholdException(
                        "An owner with the same last name and address already exists");
            }
        }
    }

    /**
     * The single source of truth for what "same household" means: identical lastName AND address,
     * each compared case-insensitively with internal whitespace collapsed. Shared with
     * {@link AssignOwnerHousehold} so the 409 bypass and the {@code householdId} assignment can
     * never drift on what counts as one household.
     */
    static boolean sameHousehold(String lastNameA, String addressA, String lastNameB, String addressB) {
        return normalize(lastNameA).equals(normalize(lastNameB))
                && normalize(addressA).equals(normalize(addressB));
    }

    /** Lower-cased, trimmed, with internal whitespace runs collapsed to a single space. */
    static String normalize(String value) {
        if (value == null) {
            return "";
        }
        return value.trim().replaceAll("\\s+", " ").toLowerCase();
    }
}
===== AssignOwnerHousehold =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

/**
 * Assigns a shared, stable {@code householdId} when the request opts in with
 * {@code sharesHousehold=true} and an existing owner shares the same household. What counts
 * as the same household — same lastName AND address, compared case-insensitively with
 * collapsed whitespace — is single-sourced in
 * {@link CheckOwnerHouseholdUnique#sameHousehold}, so the 409 bypass and this id assignment
 * agree by construction. The identifier is derived deterministically from the
 * normalized lastName and address, so every owner in one household receives the same value
 * regardless of creation order. Both the joining owner and any matching existing owner that
 * still lacks the id are stamped with it, so the household is linked on both sides. Runs
 * after {@link BuildOwner} has created the entity (and {@link CheckOwnerHouseholdUnique} has
 * allowed the collision) and before {@link SaveOwner} persists it. When the request does not
 * opt in, or opts in but no existing owner shares the household, the id is left unset.
 */
public class AssignOwnerHousehold {

    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
            return;
        }
        List<Owner> matches = new ArrayList<>();
        String shared = null;
        for (Owner existing : ownerRepository.findAll()) {
            if (existing.getId() != null && existing.getId().equals(owner.getId())) {
                continue;
            }
            if (CheckOwnerHouseholdUnique.sameHousehold(owner.getLastName(), owner.getAddress(),
                    existing.getLastName(), existing.getAddress())) {
                matches.add(existing);
                if (shared == null && existing.getHouseholdId() != null) {
                    shared = existing.getHouseholdId();
                }
            }
        }
        if (matches.isEmpty()) {
            return;
        }
        if (shared == null) {
            shared = deriveHouseholdId(CheckOwnerHouseholdUnique.normalize(owner.getLastName()),
                    CheckOwnerHouseholdUnique.normalize(owner.getAddress()));
        }
        owner.setHouseholdId(shared);
        for (Owner existing : matches) {
            if (existing.getHouseholdId() == null) {
                existing.setHouseholdId(shared);
                ownerRepository.save(existing);
            }
        }
    }

    /**
     * Derives the stable household identifier {@code HH-<12 upper hex>} from the SHA-256 of the
     * normalized {@code lastName|address}, so two owners in the same household compute the same id.
     */
    private static String deriveHouseholdId(String lastName, String address) {
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256")
                    .digest((lastName + "|" + address).getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder(12);
            for (int i = 0; i < 6; i++) {
                sb.append(String.format("%02X", digest[i]));
            }
            return "HH-" + sb.toString().toUpperCase(Locale.ROOT);
        }
        catch (NoSuchAlgorithmException ex) {
            throw new IllegalStateException("SHA-256 not available", ex);
        }
    }
}
